#include <memory>
#include <stack>
#include <string>
#include <vector>
#include <iostream>

class Recorder {
public:
    void record(const std::string& s) { lines_.push_back(s); }
    const std::vector<std::string>& lines() const { return lines_; }
private:
    std::vector<std::string> lines_;
};

// Implement: Command (virtual dtor + virtual void run()), EchoCommand
// (takes Recorder& and a message; run() records it), and CommandStack
// { push(unique_ptr<Command>), run_all(), size() }.

tests.code:
Recorder rec;
CommandStack stack;
stack.push(std::make_unique<EchoCommand>(rec, "hello"));
CHECK_EQ(stack.size(), 1);
stack.run_all();
CHECK_EQ(stack.size(), 0);
CHECK_EQ(rec.lines().size(), 1);

Recorder rec;
CommandStack stack;
stack.push(std::make_unique<EchoCommand>(rec, "first"));
stack.push(std::make_unique<EchoCommand>(rec, "second"));
stack.run_all();
CHECK_EQ(rec.lines().size(), 2);
CHECK(rec.lines()[0] == std::string("first") || rec.lines()[0] == std::string("second"));
CHECK(rec.lines()[1] != rec.lines()[0]);

Recorder rec;
CommandStack stack;
auto c = std::make_unique<EchoCommand>(rec, "moved");
stack.push(std::move(c));
CHECK_EQ(c == nullptr, true);
stack.run_all();
CHECK_EQ(rec.lines().size(), 1);
